#include <item/EffectRuntime.hpp>
#include <item/RecoveryRuntime.hpp>
#include <item/PremiumAttack.hpp>
void MultiEffectCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources)
{
    using namespace auriga::item;Check(sources.size()==34,"all 32 original fish and two seasonal bundles included");CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"multi effect private SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-multi-effect-worker").has_value(),"multi effect actual item worker starts");
    const BulkSource* human=nullptr;const BulkSource* mixed=nullptr;const BulkSource* winter=nullptr;const BulkSource* candy=nullptr;
    for(const auto& s:sources){const auto* p=TimedItemProfile(*catalog,s.grant.key);const auto* g=catalog->FindTimedEffectGroup(p->group);if(g->family==TimedEffectFamily::Fish && p->conflictBonus==BonusId::HumanDamage && !human)human=&s;if(g->family==TimedEffectFamily::Fish && catalog->FindBonus(p->bonusProfile)->Data().entries.size()>1)mixed=&s;if(g->family==TimedEffectFamily::WinterDrink)winter=&s;if(g->family==TimedEffectFamily::FestivalCandy)candy=&s;}
    Check(human && mixed && winter && candy,"actual original single/mixed fish and both seasonal source controls exist");
    for(unsigned n=0;n<sources.size()+3;++n){
        const ItemOwner owner{ItemOwnerKind::Character,71000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"multi effect owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;constexpr std::uint64_t now=1794787200000ULL;
        const auto op=[&](){return std::array<std::uint8_t,16>{0xCC,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(++serial)};};
        const auto submit=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"multi effect commit queues");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got.has_value(),"multi effect callback completes");return std::move(*got);};
        const auto apply=[&](const ItemCommit& commit){auto got=submit(commit);Check(got.write && got.state,"multi effect write saves and reloads");replay=got.write->replay;state=*got.state;};
        const auto relog=[&](){const auto before=state;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.items==before.items && state.recovery==before.recovery,"exact original bundle and debit survive new SQL session");};
        const auto grant=[&](const BulkSource& s){const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);apply(MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,s.grant,ids).value());return ids[0];};
        const auto facts=[&](ItemKey key){ItemEffectFacts f;f.alive=f.allowed=true;f.actor.context=RecoveryContext::World;f.actor.level=255;f.actor.pools={1000000,1000000,1000000,1000000};const auto* p=catalog->FindUsePolicy(catalog->Find(key)->base.usePolicy);while(!(p->allowedClasses&(1u<<f.actor.classIndex)))++f.actor.classIndex;while(!(p->allowedSexes&(1u<<f.actor.sexIndex)))++f.actor.sexIndex;return f;};
        const auto use=[&](ItemInstanceId id,std::uint64_t effect){const auto& i=*std::ranges::find(state.items,id,&PersistentItem::id);return MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,id,facts(i.key),0,now,effect);};
        const auto output=[&](const std::string& phase,const PersistentItem& source,std::uint8_t status=1,std::uint8_t error=255){const auto write=[&](const char* suffix,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+suffix+".hex");for(auto b:bytes){auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"actual multi-effect SQL state packet exported");};write("inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());write("details",EncodeTypedItemDetails(*catalog,state.items).value());write("effects",EncodeItemEffectsRuntime(*catalog,{status,error,123,456,&source,&state.recovery,state.items,now}).value());};
        if(n<sources.size()){
            const auto& spec=sources[n];const auto id=grant(spec);const auto original=state.items[0];const auto* p=TimedItemProfile(*catalog,spec.grant.key);const auto* g=catalog->FindTimedEffectGroup(p->group);output("ready",original);const auto first=use(id,1000+n).value();apply(first);Check(state.items.empty() && state.recovery.effects.size()==1 && state.recovery.effects[0].remainingMs==p->durationMs,"actual source consumed once with its complete original online duration");const auto bonuses=CollectItemEffectBonuses(*catalog,state.recovery,state.items).value();Check(bonuses==catalog->FindBonus(p->bonusProfile)->Data().entries,"all original timed bonus rows reload exactly");const auto stats=BuildEquipmentStats(*catalog,owner,state.items,bonuses).value();if(g->family>TimedEffectFamily::Fish)Check(stats.Bonus(BonusId::PremiumAttack)==500 && PremiumAttackAddition(6000,stats.Bonus(BonusId::PremiumAttack)/100)==300 && stats.Bonus(BonusId::PremiumExperience)==1000,"seasonal bundle reaches actual native stats with separate capped premium damage");output("active",original,3);auto saved=state;apply(first);Check(replay && state.items==saved.items && state.recovery==saved.recovery,"same use receipt cannot refresh or duplicate original food bundle");relog();output("relogged",original,3);
            const auto again=grant(spec);auto duplicate=use(again,2000+n);Check(!duplicate && duplicate.error().code==14 && state.items.size()==1,"active original family refuses duplicate without debit");output("denied",state.items[0],5,14);apply(MakeConsumeCommit(*catalog,op(),state.fence,state.storages,state.items,again,1).value());
            const auto actor=facts(spec.grant.key);const auto timer=[&](bool dead){auto planned=PlanRecoveryScheduleTick(*catalog,state.recovery,dead ? 0 : 123,actor.actor,dead,false);if(!planned && planned.error()==RecoveryUseError::NoEffect){auto next=AdvanceRecoverySchedule(*catalog,state.recovery,dead ? 0 : 123).value();++next.revision;planned=RecoverySchedulePlan{next};}Check(planned.has_value(),"actual food runtime timer proposal admits");auto f=actor;f.alive=!dead;NormalizeTimedItems(*catalog,planned->after,now,&f);ItemCommit commit;commit.operationId=op();commit.catalogRevision=catalog->Revision();commit.catalogHash=catalog->ContentHash();commit.kind=ItemOperationKind::Service;commit.owners={state.fence};commit.outcomeCode=0x2003;commit.result={'R','T','M',1};commit.recovery=ItemRecoveryChange{owner,state.recovery,planned->after,dead ? 0u : 123u};Check(ValidateItemCommit(*catalog,commit).has_value(),"original food exact timer commit validates");return commit;};
            auto elapsed=timer(false);apply(elapsed);Check(state.recovery.effects[0].remainingMs==p->durationMs-123,"food online duration persists exact elapsed time");saved=state;apply(elapsed);Check(replay && state.recovery==saved.recovery,"timer receipt cannot age original food twice");relog();output("elapsed",original,3);apply(timer(true));Check(state.recovery.effects.empty() && state.items.empty(),"death clears original food without resurrecting consumed source");relog();output("dead",original,3);apply(first);Check(replay && state.recovery.effects.empty() && state.items.empty(),"old use receipt cannot revive a food effect removed by death");
        }else if(n<sources.size()+2){
            const bool reverse=n==sources.size()+1;const auto first=grant(reverse ? *mixed : *human);apply(use(first,3000+n).value());const auto second=grant(reverse ? *human : *mixed);const auto original=*std::ranges::find(state.items,second,&PersistentItem::id);output(reverse ? "reverse_denied" : "mixed_ready",original,reverse ? 5 : 1,reverse ? 14 : 255);const auto next=use(second,4000+n);Check(reverse ? !next && next.error().code==14 : next.has_value(),"actual original fish overlap remains asymmetric in both directions");if(!reverse){apply(*next);Check(state.recovery.effects.size()==2,"allowed human then mixed source keeps both original bundles");output("mixed_active",original,3);relog();const auto third=grant(*human);const auto denied=use(third,5000+n);Check(!denied && denied.error().code==14,"any active fish bundle's human bonus blocks another human source");output("human_denied",*std::ranges::find(state.items,third,&PersistentItem::id),5,14);}relog();
        }else{
            const auto first=grant(*winter);apply(use(first,6000).value());const auto second=grant(*candy);const auto original=*std::ranges::find(state.items,second,&PersistentItem::id);output("food_ready",original);apply(use(second,6001).value());const auto bonuses=CollectItemEffectBonuses(*catalog,state.recovery,state.items).value();const auto stats=BuildEquipmentStats(*catalog,owner,state.items,bonuses).value();Check(state.recovery.effects.size()==2 && stats.Bonus(BonusId::PremiumAttack)==1000 && PremiumAttackAddition(1000,stats.Bonus(BonusId::PremiumAttack)/100)==100,"actual two seasonal foods coexist with exact capped native point aggregation");output("food_active",original,3);relog();output("food_relogged",original,3);
        }
    }
    store.Stop();std::cout<<"SOURCE_MULTI_EFFECT_WORKER=SUCCESS sources=34 checks="<<checks<<std::endl;
}
